// Generador de presupuestos (Oficina). Las librerías PDF están en la misma carpeta:
// pdf-lib (global PDFLib, cargada con <script>) para montar el PDF y pdf.js para la vista previa.
const pdfjsLib = await import(new URL("pdf.min.js", import.meta.url));
pdfjsLib.GlobalWorkerOptions.workerSrc = new URL("pdf.worker.min.js", import.meta.url).href;
const LOGO_JPG_B64="";

// Motor de montaje de presupuestos Gregal
// Funciona en navegador y en Node: recibe PDFLib como parámetro.

const A4W = 595.28, A4H = 841.89;
const M = 14; // margen lateral

const norm = (s) => (s || "").normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/\s+/g, "").toUpperCase();

// ---------- Análisis del resumen de Presto (texto de pdf.js) ----------
// items: textContent.items de pdf.js (transform[4]=x, transform[5]=y desde abajo)
function analyzeResumen(items, pageW, pageH) {
  const its = items.filter((i) => i.str && i.str.trim()).map((i) => ({
    s: i.str, x: i.transform[4], y: i.transform[5], h: i.height || Math.abs(i.transform[3]) || 8, w: i.width || 0,
  }));
  // agrupar en líneas
  const lines = [];
  for (const it of its.sort((a, b) => b.y - a.y || a.x - b.x)) {
    let ln = lines.find((l) => Math.abs(l.y - it.y) < 2.5);
    if (!ln) { ln = { y: it.y, h: it.h, items: [] }; lines.push(ln); }
    ln.items.push(it); ln.h = Math.max(ln.h, it.h);
  }
  lines.sort((a, b) => b.y - a.y);
  lines.forEach((l) => { l.items.sort((a, b) => a.x - b.x); l.text = l.items.map((i) => i.s).join(" ").replace(/\s+/g, " ").trim(); l.n = norm(l.text); });

  const find = (key) => lines.find((l) => l.n.includes(norm(key)));
  const title = find("RESUMEN DE PRESUPUESTO") || lines[0];
  const footer = [...lines].reverse().find((l) => /PAGINA\d*$/.test(l.n) || l.n.includes("PAGINA"));
  const idx = lines.indexOf(title);
  const obraLine = lines[idx + 1];
  const obra = obraLine && !obraLine.n.startsWith("CAPITULO") ? obraLine.text : "";

  const minX = Math.min(...its.map((i) => i.x));
  const maxX = Math.max(...its.map((i) => i.x + i.w));
  const below = (l, pad = 7) => (l ? l.y - pad : null);
  const stops = {
    pem: below(find("EJECUCION MATERIAL")),
    total: below(find("TOTAL PRESUPUESTO GENERAL")),
    asciende: below(find("Asciende el presupuesto")),
    firmas: find("El promotor") ? Math.max(find("El promotor").y - 45, footer ? footer.y + footer.h + 8 : 30)
      : footer ? footer.y + footer.h + 8 : 40,
  };
  const lastNum = (l) => { if (!l) return ""; const m = l.text.match(/(-?[\d.]+,\d{2})\s*$/); return m ? m[1] : ""; };
  const totals = {
    pem: lastNum(find("EJECUCION MATERIAL")),
    total: lastNum(find("TOTAL PRESUPUESTO GENERAL")),
    letra: (find("Asciende el presupuesto")?.text || "").replace(/^.*cantidad de\s*/i, "").replace(/\s+/g, " ").trim(),
  };
  // Líneas que se eliminan del resumen (con su raya superior)
  const skip = [];
  const contrata = find("EJECUCION POR CONTRATA");
  if (contrata) skip.push({ top: contrata.y + contrata.h + 5, bottom: contrata.y - 3.5 });
  return {
    obra,
    totals,
    skip,
    top: title.y + title.h + 4,
    left: Math.max(0, minX - 6),
    right: Math.min(pageW, maxX + 6),
    stops,
    footerY: footer ? footer.y : null,
  };
}

// ---------- Utilidades de dibujo ----------
function makeSafe(font) {
  const set = new Set(font.getCharacterSet());
  const map = { "\t": " ", "–": "-", "—": "-", "‘": "'", "’": "'", "“": '"', "”": '"', " ": " " };
  return (s) => Array.from(String(s ?? "").replace(/\r/g, "")).map((ch) => (ch === "\n" || set.has(ch.codePointAt(0)) ? ch : map[ch] ?? "?")).join("");
}

function wrap(text, font, size, maxW) {
  const out = [];
  for (const para of String(text || "").split(/\r?\n/)) {
    if (!para.trim()) { out.push(""); continue; }
    let line = "";
    for (const word of para.split(/\s+/)) {
      const t = line ? line + " " + word : word;
      if (font.widthOfTextAtSize(t, size) <= maxW) line = t;
      else {
        if (line) out.push(line);
        // palabra demasiado larga: cortar
        let w = word;
        while (font.widthOfTextAtSize(w, size) > maxW && w.length > 1) {
          let k = w.length;
          while (k > 1 && font.widthOfTextAtSize(w.slice(0, k), size) > maxW) k--;
          out.push(w.slice(0, k)); w = w.slice(k);
        }
        line = w;
      }
    }
    out.push(line);
  }
  return out;
}

function fitText(text, font, size, maxW, min = 6) {
  let s = size;
  while (s > min && font.widthOfTextAtSize(text, s) > maxW) s -= 0.25;
  return s;
}

// ---------- Construcción del PDF ----------
// opts: { prestoBytes, resumenBytes, logoBytes, data, crop:{top,bottom,left,right}, coverOnly }
async function buildPdf(PDFLib, opts) {
  const { PDFDocument, StandardFonts, rgb } = PDFLib;
  const d = opts.data || {};
  const out = await PDFDocument.create();
  const reg = await out.embedFont(StandardFonts.Helvetica);
  const bold = await out.embedFont(StandardFonts.HelveticaBold);
  const sReg = makeSafe(reg), sBold = makeSafe(bold);

  const NAVY = rgb(0, 0, 121 / 255);
  const LAV = rgb(210 / 255, 210 / 255, 1);
  const LAV2 = rgb(239 / 255, 239 / 255, 1);
  const GREY = rgb(239 / 255, 239 / 255, 239 / 255);
  const GREYB = rgb(0.78, 0.78, 0.78);
  const TXT = rgb(0.15, 0.15, 0.17);
  const TXT2 = rgb(0.26, 0.26, 0.27);

  const p = out.addPage([A4W, A4H]);
  const Y = (t) => A4H - t; // coordenadas desde arriba
  const text = (s, x, t, { f = reg, size = 8, color = TXT, maxW } = {}) => {
    const safe = (f === bold ? sBold : sReg)(s);
    const sz = maxW ? fitText(safe, f, size, maxW) : size;
    p.drawText(safe, { x, y: Y(t), size: sz, font: f, color });
  };
  const box = (x, t, w, h, o = {}) => p.drawRectangle({ x, y: Y(t + h), width: w, height: h, ...o });
  const hline = (x1, x2, t, th, color = NAVY) => p.drawLine({ start: { x: x1, y: Y(t) }, end: { x: x2, y: Y(t) }, thickness: th, color });

  const R = A4W - M; // borde derecho

  // --- Caja cliente ---
  // --- Caja con los datos de la empresa (fija) ---
  box(M, 14, 250, 114, { color: GREY, borderColor: GREYB, borderWidth: 0.6 });
  const emp = [
    ["Gregal Ingeniería de Instalaciones SL", bold],
    ["B26750430", reg],
    ["Paseo Del Ferrocarril, 50", reg],
    ["07500", reg],
    ["Manacor", reg],
  ];
  let ct = 39;
  for (const [s, f] of emp) { text(s, M + 5, ct, { f, size: 9.5, maxW: 238 }); ct += 17.8; }

  // --- Logo ---
  if (opts.logoBytes) {
    const img = await out.embedJpg(opts.logoBytes);
    const lw = 270, lh = (lw * img.height) / img.width;
    p.drawImage(img, { x: R - lw - 4, y: Y(44 + lh), width: lw, height: lh });
  }

  // --- Título ---
  const titulo = sBold(d.titulo || "");
  const tl = wrap(titulo, bold, 11.5, 292);
  if (tl.length <= 2) tl.forEach((l, i) => text(l, M + 3, 173 + i * 13 - (tl.length - 1) * 6, { f: bold, size: 11.5, color: TXT2 }));
  else wrap(titulo, bold, 9, 292).slice(0, 3).forEach((l, i) => text(l, M + 3, 163 + i * 11, { f: bold, size: 9, color: TXT2 }));

  // --- Tabla documento ---
  const tx = 318, tw = R - tx;
  box(tx, 162, tw, 16, { color: LAV, borderColor: NAVY, borderWidth: 0.75 });
  const cols = [tx + 8, tx + 85, tx + 156, tx + 210];
  ["DOCUMENTO", "NÚMERO", "PÁGINA", "FECHA"].forEach((h, i) => text(h, cols[i], 174, { f: bold, size: 7, color: TXT }));
  text(d.documento || "Presupuesto", cols[0], 190, { size: 8, maxW: 74 });
  text(d.numero || "", cols[1], 190, { size: 8, maxW: 68 });
  text(d.pagina || "1", cols[2], 190, { size: 8, maxW: 50 });
  text(d.fecha || "", cols[3], 190, { size: 8, maxW: R - cols[3] - 2 });
  hline(tx, R, 197, 1.5);

  // --- Barra NIF / agente / forma de pago ---
  box(M, 207, R - M, 15, { color: LAV, borderColor: NAVY, borderWidth: 0.75 });
  box(M, 222, R - M, 14, { color: LAV2 });
  const bc = [M + 8, M + 125, M + 372];
  ["N.I.F.", "AGENTE", "FORMA DE PAGO"].forEach((h, i) => text(h, bc[i], 218, { f: bold, size: 7 }));
  text(d.nifCliente || "", bc[0], 232, { size: 8, maxW: 110 });
  text(d.agente || "", bc[1], 232, { size: 8, maxW: 240 });
  text(d.formaPago || "", bc[2], 232, { size: 8, maxW: R - bc[2] - 4 });
  hline(M, R, 243, 2);

  // --- Notas (abajo) ---
  const NOTE_SIZE = 8.5, NOTE_LH = 11;
  const footerT = 826;
  let noteLines = wrap(sReg(d.notas || ""), reg, NOTE_SIZE, R - M - 16);
  while (noteLines.length && !noteLines[noteLines.length - 1].trim()) noteLines.pop();
  const maxNoteLines = 22;
  if (noteLines.length > maxNoteLines) noteLines = noteLines.slice(0, maxNoteLines);
  const notesBodyH = Math.max(46, noteLines.length * NOTE_LH + 12);
  const notesTop = footerT - 14 - notesBodyH - 15;
  box(M, notesTop, R - M, 15, { color: LAV, borderColor: NAVY, borderWidth: 0.75 });
  text("NOTAS", M + 8, notesTop + 11, { f: bold, size: 7.5 });
  box(M, notesTop + 15, R - M, notesBodyH, { borderColor: LAV, borderWidth: 0.9 });
  noteLines.forEach((l, i) => text(l, M + 8, notesTop + 15 + 13 + i * NOTE_LH, { size: NOTE_SIZE }));

  // --- Pie con datos de la empresa ---
  const pie = d.pie ?? "";
  if (pie) {
    const s = sReg(pie), sz = fitText(s, reg, 7, R - M);
    p.drawText(s, { x: (A4W - reg.widthOfTextAtSize(s, sz)) / 2, y: Y(footerT + 4), size: sz, font: reg, color: rgb(0.45, 0.45, 0.48) });
  }

  // --- Resumen de presupuesto incrustado ---
  if (opts.resumenBytes) {
    const rdoc = await PDFDocument.load(opts.resumenBytes, { ignoreEncryption: true });
    const rp = rdoc.getPage(0);
    const { width: rw, height: rh } = rp.getSize();
    const c = opts.crop || { top: rh - 20, bottom: 40, left: 15, right: rw - 15 };
    // tramos visibles (de arriba abajo), quitando las zonas "skip"
    let segs = [[c.top, c.bottom]];
    for (const s of (c.skip || []).slice().sort((a, b) => b.top - a.top)) {
      const next = [];
      for (const [t, b] of segs) {
        if (s.bottom >= t || s.top <= b) { next.push([t, b]); continue; }
        if (s.top < t) next.push([t, s.top]);
        if (s.bottom > b) next.push([s.bottom, b]);
      }
      segs = next;
    }
    segs = segs.filter(([t, b]) => t - b > 0.5);
    const cw = c.right - c.left, chh = segs.reduce((a, [t, b]) => a + (t - b), 0);
    const areaTop = 252, areaBottom = notesTop - 10;
    const availW = R - M - 10, availH = areaBottom - areaTop;
    const sc = Math.min(availW / cw, availH / chh, 1.05);
    const dw = cw * sc;
    let cur = areaTop;
    for (const [t, b] of segs) {
      const emb = await out.embedPage(rp, { left: c.left, bottom: b, right: c.right, top: t });
      const h = (t - b) * sc;
      p.drawPage(emb, { x: (A4W - dw) / 2, y: Y(cur + h), xScale: sc, yScale: sc });
      cur += h;
    }
  }

  // --- Presupuesto Presto completo ---
  if (opts.prestoBytes && !opts.coverOnly) {
    const src = await PDFDocument.load(opts.prestoBytes, { ignoreEncryption: true });
    const pages = await out.copyPages(src, src.getPageIndices());
    pages.forEach((pg) => out.addPage(pg));
  }

  out.setTitle(sReg(d.titulo || "Presupuesto"));
  out.setAuthor("Gregal Ingeniería de Instalaciones SL");
  out.setProducer("Gregal - Montaje de presupuestos");
  return await out.save();
}

const PDFLib = window.PDFLib;
const $ = (s) => document.querySelector(s);
const logoBytes = Uint8Array.from(atob(LOGO_JPG_B64), (c) => c.charCodeAt(0));

const state = { presto: null, prestoName: "", prestoPages: 0, resumen: null, analysis: null };

// ---------- almacenamiento local (opcional) ----------
const store = {
  get(k, d) { try { const v = localStorage.getItem("gregal." + k); return v == null ? d : JSON.parse(v); } catch { return d; } },
  set(k, v) { try { localStorage.setItem("gregal." + k, JSON.stringify(v)); } catch {} },
};

// fecha por defecto: hoy
const today = new Date();
$("#fecha").value = today.toISOString().slice(0, 10);
const fmtDate = (v) => { if (!v) return ""; const [y, m, d] = v.split("-"); return `${d}/${m}/${y}`; };

// recordar campos marcados
document.querySelectorAll("[data-remember]").forEach((el) => {
  const v = store.get("f." + el.dataset.k, null);
  if (v != null) el.value = v;
  el.addEventListener("change", () => store.set("f." + el.dataset.k, el.value));
});

function readData() {
  const d = {};
  document.querySelectorAll("[data-k]").forEach((el) => (d[el.dataset.k] = el.value.trim()));
  d.notas = document.querySelector('[data-k="notas"]').value; // conservar saltos
  d.fecha = fmtDate($("#fecha").value);
  return d;
}

// ---------- notas automáticas ----------
let notasEditadas = false;
function generarNotas() {
  const a = state.analysis || {};
  const t = a.totals || {};
  const d = readData();
  const l = [];
  if (a.obra) l.push(`Obra: ${a.obra}.`);
  if (t.total && t.total !== "0,00") l.push(`Importe total del presupuesto: ${t.total} €${t.letra ? " (" + t.letra.toLowerCase() + ")" : ""}, impuestos incluidos.`);
  else if (t.pem && t.pem !== "0,00") l.push(`Presupuesto de ejecución material: ${t.pem} €.`);
  if (d.formaPago) l.push(`Forma de pago: ${d.formaPago}.`);
  l.push(`Presupuesto válido durante 30 días desde su fecha de emisión${d.fecha ? " (" + d.fecha + ")" : ""}.`);
  l.push("Los trabajos no incluidos en las mediciones del presente presupuesto se valorarán aparte.");
  return l.join("\n");
}
function autoNotas(force = false) {
  if (notasEditadas && !force) return;
  $("#notas").value = generarNotas();
  notasEditadas = false;
}
$("#notas").addEventListener("input", () => (notasEditadas = true));
$("#regen").addEventListener("click", () => { autoNotas(true); schedulePreview(); });
["#fecha", '[data-k="formaPago"]'].forEach((q) => $(q).addEventListener("input", () => autoNotas()));

function say(t, cls = "") { const m = $("#msg"); m.textContent = t; m.className = "msg " + cls; }

// ---------- carga de ficheros ----------
function setupDrop(dropId, inputId, onFile) {
  const drop = $(dropId), input = $(inputId);
  input.addEventListener("change", () => input.files[0] && onFile(input.files[0], drop));
  ["dragenter", "dragover"].forEach((ev) => drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.add("over"); }));
  ["dragleave", "drop"].forEach((ev) => drop.addEventListener(ev, () => drop.classList.remove("over")));
  drop.addEventListener("drop", (e) => { e.preventDefault(); const f = e.dataTransfer.files[0]; if (f) onFile(f, drop); });
}
const readFile = (f) => f.arrayBuffer().then((b) => new Uint8Array(b));

setupDrop("#dropPresto", "#filePresto", async (f, drop) => {
  try {
    const bytes = await readFile(f);
    const doc = await PDFLib.PDFDocument.load(bytes, { ignoreEncryption: true });
    state.presto = bytes; state.prestoName = f.name; state.prestoPages = doc.getPageCount();
    drop.classList.add("ok");
    drop.querySelector("small").textContent = `${f.name} · ${state.prestoPages} págs.`;
    say(""); updateButton(); updateMeta();
  } catch (e) { say("No se ha podido leer el presupuesto: " + e.message, "err"); }
});

setupDrop("#dropResumen", "#fileResumen", async (f, drop) => {
  try {
    const bytes = await readFile(f);
    const doc = await pdfjsLib.getDocument({ data: bytes.slice() }).promise;
    const page = await doc.getPage(1);
    const vp = page.getViewport({ scale: 1 });
    const tc = await page.getTextContent();
    state.analysis = analyzeResumen(tc.items, vp.width, vp.height);
    state.resumen = bytes;
    drop.classList.add("ok");
    drop.querySelector("small").textContent = f.name;
    const t = document.querySelector('[data-k="titulo"]');
    if (!t.value && state.analysis.obra) t.value = "Presupuesto instalaciones - " + state.analysis.obra;
    // marcar opciones no disponibles
    for (const o of $("#stop").options) o.disabled = state.analysis.stops[o.value] == null;
    $("#stop").value = !$("#stop").querySelector('[value="total"]').disabled ? "total" : "firmas";
    autoNotas();
    say(""); updateButton(); schedulePreview();
  } catch (e) { say("No se ha podido leer el resumen: " + e.message, "err"); }
});

function cropFor() {
  const a = state.analysis; if (!a) return null;
  const bottom = a.stops[$("#stop").value] ?? a.stops.firmas;
  return { top: a.top, bottom, left: a.left, right: a.right, skip: a.skip || [] };
}
function updateButton() { $("#go").disabled = !(state.presto && state.resumen); }
function updateMeta() {
  $("#meta").textContent = state.presto ? `PDF final: portada + ${state.prestoPages} páginas de Presto = ${state.prestoPages + 1} páginas` : "";
}

// ---------- vista previa ----------
let timer = null, busy = false, again = false;
function schedulePreview() { clearTimeout(timer); timer = setTimeout(renderPreview, 250); }
async function renderPreview() {
  if (!state.resumen) return;
  if (busy) { again = true; return; }
  busy = true;
  try {
    const bytes = await buildPdf(PDFLib, { resumenBytes: state.resumen, logoBytes, data: readData(), crop: cropFor(), coverOnly: true });
    const task = pdfjsLib.getDocument({ data: bytes });
    const doc = await task.promise;
    const page = await doc.getPage(1);
    const scale = 2;
    const vp = page.getViewport({ scale });
    let canvas = $("#frame canvas");
    if (!canvas) { $("#frame").innerHTML = ""; canvas = document.createElement("canvas"); $("#frame").appendChild(canvas); }
    const off = document.createElement("canvas");
    off.width = vp.width; off.height = vp.height;
    await page.render({ canvasContext: off.getContext("2d"), viewport: vp }).promise;
    canvas.width = off.width; canvas.height = off.height;
    canvas.getContext("2d").drawImage(off, 0, 0);
    task.destroy();
  } catch (e) { say("Error en la vista previa: " + e.message, "err"); }
  busy = false;
  if (again) { again = false; renderPreview(); }
}
document.querySelector(".presupuestos").querySelectorAll("input, textarea, select").forEach((el) => el.addEventListener("input", schedulePreview));
$("#stop").addEventListener("change", schedulePreview);

// ---------- descarga ----------
let downloads = null;
if (window.claude && typeof window.claude.use === "function") {
  window.claude.use("downloads").then((d) => (downloads = d)).catch(() => {});
}
const safeName = (s) => s.replace(/[\\/:*?"<>|]+/g, "-").replace(/\s+/g, " ").trim();

$("#go").addEventListener("click", async () => {
  const btn = $("#go"); btn.disabled = true; say("Generando PDF…");
  try {
    const d = readData();
    const bytes = await buildPdf(PDFLib, { prestoBytes: state.presto, resumenBytes: state.resumen, logoBytes, data: d, crop: cropFor() });
    const base = safeName([d.numero, d.titulo || "Presupuesto"].filter(Boolean).join(" - ")) || "Presupuesto";
    const filename = base.slice(0, 180) + ".pdf";
    const blob = new Blob([bytes], { type: "application/pdf" });
    if (downloads) {
      try { await downloads.save({ filename, data: blob }); say(`Listo: ${filename}`, "ok"); }
      catch (e) { say(e && e.code === "declined" ? "Descarga cancelada." : "No se ha podido descargar: " + (e.message || e.code), e && e.code === "declined" ? "" : "err"); }
    } else {
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob); a.download = filename; document.body.appendChild(a); a.click();
      setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 2000);
      say(`Listo: ${filename}`, "ok");
    }
    store.set("f.agente", d.agente); store.set("f.formaPago", d.formaPago);
  } catch (e) { say("Error al generar el PDF: " + e.message, "err"); }
  updateButton();
});
